const express = require('express');
const router = express.Router();
const multer = require('multer');
const crypto = require('crypto');
const db = require('../config/supabase');
const { extractText } = require('../services/documentExtractor');
const { normalizeDentalEntities, extractToothNumbers } = require('../services/dentalNormalizer');
const { identifyCdtCandidates, getCdtKnowledge } = require('../services/cdtKnowledgeBase');
const geminiService = require('../services/geminiService');

const upload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 20 * 1024 * 1024 } // 20MB
});

// In-memory store for assessment sessions when local mode is active
const assessmentSessions = new Map();

/**
 * Helper: Extract clinical details, patient identifiers, and dental entities from text
 */
function extractClinicalEntitiesFromText(combinedText = '', docName = '') {
  if (!combinedText || !combinedText.trim()) {
    return {
      patient_name: null,
      patient_id: null,
      patient_age: null,
      doctor_name: null,
      treatment_date: null,
      teeth: [],
      cdt_code: null,
      diagnoses: [],
      findings: [],
      structural_findings: [],
      treatment_context: [],
      clinical_justification: null,
      measurements: [],
      materials: [],
      keywords: [],
      previous_rejection: null
    };
  }

  const text = combinedText;

  // 1. Patient Name extraction (Support flexible clinical header formats)
  let patientName = null;
  const nameMatch = text.match(/(?:Patient(?:\s*Name)?|Pt\.?(?:\s*Name)?|Name|Insured(?:\s*Name)?|Member(?:\s*Name)?|Client)\s*[:#-]*\s*([A-Za-z'\s.]{2,40})(?=\r?\n|,|\.|\t|DOB|ID|Age|DOS|Date|$)/i);
  if (nameMatch && nameMatch[1]) {
    const cleaned = nameMatch[1].trim();
    if (!/^(unknown|none|n\/a|not specified|patient|doctor|provider)$/i.test(cleaned)) {
      patientName = cleaned;
    }
  }

  // 2. Patient ID extraction
  let patientId = null;
  const idMatch = text.match(/(?:Patient\s*ID|Pt\s*ID|Record\s*#?|MRN|Chart\s*#?|Policy\s*#?|Member\s*ID|Subscriber\s*ID|ID)\s*[:#\s]*([A-Z0-9-]{3,25})/i);
  if (idMatch && idMatch[1]) {
    const cleanedId = idMatch[1].trim();
    if (!/^(unknown|none|n\/a)$/i.test(cleanedId)) {
      patientId = cleanedId;
    }
  }

  // 3. Patient Age
  let patientAge = null;
  const ageMatch = text.match(/\b(?:Age|Age\s*[:=])\s*(\d{1,3})\b/i);
  if (ageMatch && ageMatch[1]) {
    const parsedAge = parseInt(ageMatch[1], 10);
    if (parsedAge > 0 && parsedAge < 125) {
      patientAge = parsedAge;
    }
  }

  // 4. Doctor / Provider Name
  let doctorName = null;
  const drMatch = text.match(/(?:Dr\.?|Doctor|Provider|Dentist|Treating\s*Doctor|Physician|Surgeon)\s*[:#\s]*([A-Za-z'\s.]{2,40})(?=\r?\n|,|\.|\t|DDS|DMD|Lic|$)/i);
  if (drMatch && drMatch[1]) {
    const cleanedDr = drMatch[1].trim();
    if (!/^(unknown|none|n\/a)$/i.test(cleanedDr)) {
      doctorName = cleanedDr.startsWith('Dr') ? cleanedDr : `Dr. ${cleanedDr}`;
    }
  }

  // 5. Treatment Date / DOS
  let treatmentDate = null;
  const dosMatch = text.match(/(?:Date\s*of\s*Service|DOS|Treatment\s*Date|Date\s*of\s*Treatment|Procedure\s*Date|Date)\s*[:\s]*(\d{4}[-/.]\d{1,2}[-/.]\d{1,2}|\d{1,2}[-/.]\d{1,2}[-/.]\d{2,4})/i);
  if (dosMatch && dosMatch[1]) {
    treatmentDate = dosMatch[1].trim();
  }

  // 6. Teeth numbers
  const teeth = extractToothNumbers(text);

  // 7. Explicit CDT code mention
  let cdtCode = null;
  const cdtMatch = text.match(/\b(D\d{4})\b/i);
  if (cdtMatch && cdtMatch[1]) {
    cdtCode = cdtMatch[1].toUpperCase();
  }

  // 8. Dynamic term extraction strictly from input text
  const diagnoses = [];
  const structuralFindings = [];
  const treatmentContext = [];

  const lowerText = text.toLowerCase();

  const termRules = [
    { cat: 'diag', label: 'recurrent caries', regex: /\brecurrent (?:caries|decay)\b/i },
    { cat: 'diag', label: 'caries into dentin', regex: /\b(?:caries|decay)\s+(?:into|involving)\s+dentin\b/i },
    { cat: 'diag', label: 'periapical radiolucency', regex: /\bperiapical radiolucency\b/i },
    { cat: 'diag', label: 'periodontitis', regex: /\bperiodontitis\b/i },
    { cat: 'diag', label: 'abscess', regex: /\babscess\b/i },
    { cat: 'diag', label: 'irreversible pulpitis', regex: /\birreversible pulpitis\b/i },
    { cat: 'diag', label: 'bone loss', regex: /\b(?:alveolar|crestal)?\s*bone loss\b/i },
    { cat: 'struct', label: 'compromised coronal structure', regex: /\bcompromised coronal structure\b/i },
    { cat: 'struct', label: 'cusp fracture', regex: /\bcusp(?:al)? fracture\b/i },
    { cat: 'struct', label: 'cracked tooth', regex: /\bcracked tooth\b/i },
    { cat: 'struct', label: 'extensive structural breakdown', regex: /\bextensive structural breakdown\b/i },
    { cat: 'struct', label: 'insufficient tooth structure', regex: /\binsufficient (?:sound )?tooth structure\b/i },
    { cat: 'struct', label: 'undermined enamel', regex: /\bundermined enamel\b/i },
    { cat: 'treat', label: 'porcelain crown', regex: /\bporcelain crown\b/i },
    { cat: 'treat', label: 'root canal therapy', regex: /\broot canal\b/i },
    { cat: 'treat', label: 'scaling and root planing', regex: /\bscaling (?:and|&) root planing\b/i },
    { cat: 'treat', label: 'surgical extraction', regex: /\bsurgical extraction\b/i }
  ];

  termRules.forEach(rule => {
    if (rule.regex.test(text)) {
      if (rule.cat === 'diag') diagnoses.push(rule.label);
      if (rule.cat === 'struct') structuralFindings.push(rule.label);
      if (rule.cat === 'treat') treatmentContext.push(rule.label);
    }
  });

  // 9. Measurements & Percentages (e.g. 5mm, 60% coronal structure loss)
  const measurements = [];
  const depthMatches = text.match(/\b\d+(?:\.\d+)?\s*(?:mm|millimeter)\b/gi) || [];
  const percentMatches = text.match(/\b\d+(?:\.\d+)?\s*%/gi) || [];
  depthMatches.forEach(m => measurements.push(`Pocket/depth: ${m}`));
  percentMatches.forEach(m => measurements.push(`Structure/loss: ${m}`));

  // 10. Materials detected
  const materials = [];
  const matPatterns = [
    { label: 'Porcelain / Ceramic', regex: /\b(?:porcelain|ceramic|e\.?max|zirconia)\b/i },
    { label: 'Resin Composite', regex: /\b(?:composite|resin)\b/i },
    { label: 'Gold / Precious Metal', regex: /\b(?:cast gold|noble metal|high noble)\b/i },
    { label: 'Porcelain Fused to Metal (PFM)', regex: /\b(?:pfm|porcelain fused to metal)\b/i },
    { label: 'Amalgam', regex: /\b(?:amalgam)\b/i }
  ];
  matPatterns.forEach(p => {
    if (p.regex.test(text)) materials.push(p.label);
  });

  // 11. Clinical Justification sentence extraction
  let justification = null;
  const justMatch = text.match(/(?:justification|necessity|rationale|clinical reason|indicated because|requires full coverage)\s*[:\s-]*([^\r\n.;]+(?:\.[^\r\n.;]+)?)/i);
  if (justMatch && justMatch[1]) {
    justification = justMatch[1].trim();
  }

  // 12. Relevant Clinical Keywords
  const keywords = [];
  const kwList = [
    'recurrent caries', 'decay into dentin', 'compromised coronal structure',
    'cusp fracture', 'cracked tooth', 'subgingival margin', 'bone loss',
    'periodontal pocket', 'furcation involvement', 'periapical radiolucency',
    'root fracture', 'irreversible pulpitis', 'non-restorable'
  ];
  kwList.forEach(kw => {
    if (new RegExp(`\\b${kw}\\b`, 'i').test(text)) {
      keywords.push(kw);
    }
  });

  // 13. Previous Rejection / Denial Report details (if applicable)
  let previousRejection = null;
  const denialReasonMatch = text.match(/(?:denial\s*reason|rejection\s*reason|reason\s*for\s*denial|denied\s*due\s*to|adjudication\s*remark)\s*[:\s]*([^\r\n;]+)/i);
  const denialCodeMatch = text.match(/(?:denial\s*code|carc|rarc|remark\s*code)\s*[:\s]*([A-Z0-9-]+)/i);
  if (denialReasonMatch || denialCodeMatch || /claim\s*denied|rejection\s*notice|audit\s*rejection/i.test(text)) {
    previousRejection = {
      detected: true,
      reason: denialReasonMatch ? denialReasonMatch[1].trim() : 'Previous claim rejection/denial documented in uploaded file',
      code: denialCodeMatch ? denialCodeMatch[1].trim() : null,
      document_source: docName || 'Uploaded report'
    };
  }

  return {
    patient_name: patientName,
    patient_id: patientId,
    patient_age: patientAge,
    doctor_name: doctorName,
    treatment_date: treatmentDate,
    teeth: teeth,
    cdt_code: cdtCode,
    diagnoses: diagnoses,
    findings: diagnoses,
    structural_findings: structuralFindings,
    treatment_context: treatmentContext,
    clinical_justification: justification,
    measurements,
    materials,
    keywords,
    previous_rejection: previousRejection
  };
}

/**
 * POST /api/assessment/extract
 * Accepts multiple uploaded files and/or raw clinical text note.
 * Actually parses documents using pdf-parse or plain text readers and runs extraction.
 */
router.post('/extract', upload.array('files', 10), async (req, res) => {
  try {
    const rawNote = req.body.clinical_note || req.body.narrative || '';
    const files = req.files || [];

    const extractedDocuments = [];
    let combinedText = rawNote;

    for (const file of files) {
      const originalName = file.originalname || 'document';
      const mimeType = file.mimetype || '';
      const extraction = await extractText(file.buffer, mimeType, originalName);

      extractedDocuments.push({
        id: crypto.randomUUID(),
        file_name: originalName,
        mime_type: mimeType,
        file_size: file.size,
        word_count: extraction.word_count,
        is_image_only: extraction.is_image_only,
        ocr_required: extraction.ocr_required,
        extracted_text: extraction.text,
        document_type: req.body[`doc_type_${originalName}`] || 'CLINICAL_NOTE'
      });

      if (!extraction.is_image_only && extraction.text) {
        combinedText += `\n--- Document: ${originalName} ---\n${extraction.text}\n`;
      }
    }

    let clinicalData = extractClinicalEntitiesFromText(combinedText, files.length > 0 ? files[0].originalname : '');
    let cdtCandidates = [];
    let aiEngine = 'Deterministic Dental Ontology';
    let geminiDentalAssessment = null;

    // Use Google Gemini AI for deep dental analysis when configured
    if (geminiService.isGeminiConfigured()) {
      try {
        const geminiResult = await geminiService.analyzeDentalClinicalWithGemini({
          clinicalNarrative: rawNote,
          documentTexts: extractedDocuments.map(d => d.extracted_text),
          previousDenialText: clinicalData.previous_rejection?.reason || ''
        });

        if (geminiResult) {
          aiEngine = 'Google Gemini 2.5 Flash';
          geminiDentalAssessment = geminiResult.dental_readiness_assessment || null;

          // Merge authentic extractions from Gemini
          clinicalData = {
            patient_name: (geminiResult.patient_name && geminiResult.patient_name !== 'Not found') ? geminiResult.patient_name : clinicalData.patient_name,
            patient_id: (geminiResult.patient_id && geminiResult.patient_id !== 'Not found') ? geminiResult.patient_id : clinicalData.patient_id,
            patient_age: (geminiResult.patient_age && geminiResult.patient_age !== 'Not found') ? geminiResult.patient_age : clinicalData.patient_age,
            doctor_name: (geminiResult.doctor_name && geminiResult.doctor_name !== 'Not found') ? geminiResult.doctor_name : clinicalData.doctor_name,
            treatment_date: (geminiResult.treatment_date && geminiResult.treatment_date !== 'Not found') ? geminiResult.treatment_date : clinicalData.treatment_date,
            teeth: (geminiResult.teeth && geminiResult.teeth.length > 0) ? geminiResult.teeth : clinicalData.teeth,
            surfaces: geminiResult.surfaces || [],
            quadrant: geminiResult.quadrant || null,
            cdt_code: clinicalData.cdt_code,
            diagnoses: (geminiResult.diagnoses && geminiResult.diagnoses.length > 0) ? geminiResult.diagnoses : clinicalData.diagnoses,
            findings: (geminiResult.diagnoses && geminiResult.diagnoses.length > 0) ? geminiResult.diagnoses : clinicalData.findings,
            structural_findings: (geminiResult.structural_findings && geminiResult.structural_findings.length > 0) ? geminiResult.structural_findings : clinicalData.structural_findings,
            remaining_structure_percentage: geminiResult.remaining_structure_percentage || null,
            pulpal_periapical_status: geminiResult.pulpal_periapical_status || null,
            periodontal_findings: geminiResult.periodontal_findings || null,
            treatment_context: clinicalData.treatment_context,
            clinical_justification: geminiResult.clinical_justification || clinicalData.clinical_justification,
            measurements: (geminiResult.measurements && geminiResult.measurements.length > 0) ? geminiResult.measurements : clinicalData.measurements,
            materials: (geminiResult.materials && geminiResult.materials.length > 0) ? geminiResult.materials : clinicalData.materials,
            keywords: (geminiResult.keywords && geminiResult.keywords.length > 0) ? geminiResult.keywords : clinicalData.keywords,
            previous_rejection: geminiResult.previous_rejection_analysis || clinicalData.previous_rejection
          };

          if (Array.isArray(geminiResult.suggested_cdt_codes) && geminiResult.suggested_cdt_codes.length > 0) {
            cdtCandidates = geminiResult.suggested_cdt_codes;
          }
        }
      } catch (geminiErr) {
        console.warn('[Assessment] Gemini dental extraction fallback:', geminiErr.message);
      }
    }

    // Fallback to deterministic CDT candidates if Gemini not configured or produced no candidates
    if (cdtCandidates.length === 0) {
      const normalized = {
        findings: clinicalData.findings,
        structural_findings: clinicalData.structural_findings,
        treatment_context: clinicalData.treatment_context,
        severity: []
      };
      cdtCandidates = identifyCdtCandidates(normalized, combinedText);
    }

    return res.json({
      success: true,
      ai_engine: aiEngine,
      data: {
        documents: extractedDocuments,
        extracted_info: {
          patient_name: clinicalData.patient_name || 'Not found',
          patient_id: clinicalData.patient_id || 'Not found',
          patient_age: clinicalData.patient_age !== null ? clinicalData.patient_age : 'Not found',
          doctor_name: clinicalData.doctor_name || 'Not found',
          treatment_date: clinicalData.treatment_date || 'Not found',
          teeth: clinicalData.teeth.length > 0 ? clinicalData.teeth : 'Not found',
          surfaces: (clinicalData.surfaces && clinicalData.surfaces.length > 0) ? clinicalData.surfaces : 'Not found',
          quadrant: clinicalData.quadrant || 'Not found',
          cdt_code: clinicalData.cdt_code || 'Not found',
          diagnoses: clinicalData.diagnoses.length > 0 ? clinicalData.diagnoses : 'Not found',
          findings: clinicalData.findings.length > 0 ? clinicalData.findings : 'Not found',
          structural_findings: clinicalData.structural_findings.length > 0 ? clinicalData.structural_findings : 'Not found',
          remaining_structure_percentage: clinicalData.remaining_structure_percentage || 'Not specified',
          pulpal_periapical_status: clinicalData.pulpal_periapical_status || 'Not found',
          treatment_context: clinicalData.treatment_context.length > 0 ? clinicalData.treatment_context : 'Not found',
          clinical_justification: clinicalData.clinical_justification || 'Not found',
          measurements: clinicalData.measurements.length > 0 ? clinicalData.measurements : 'Not found',
          materials: clinicalData.materials.length > 0 ? clinicalData.materials : 'Not found',
          keywords: clinicalData.keywords.length > 0 ? clinicalData.keywords : 'Not found',
          previous_rejection: clinicalData.previous_rejection || null,
          dental_readiness_assessment: geminiDentalAssessment
        },
        cdt_candidates: cdtCandidates,
        raw_combined_length: combinedText.length
      }
    });
  } catch (err) {
    console.error('[Assessment Extract Error]:', err);
    return res.status(500).json({ success: false, message: err.message });
  }
});

/**
 * POST /api/assessment/verify-payer-url
 * Fetches and analyzes publicly available payer policy text from a provided URL.
 * Compares scraped website policy criteria against uploaded document text & clinical narrative.
 */
router.post('/verify-payer-url', async (req, res) => {
  const { url, payer_name, documents = [], clinical_narrative = '', procedure = {} } = req.body;

  if (!url || typeof url !== 'string' || !url.trim().startsWith('http')) {
    return res.status(400).json({
      success: false,
      verified: false,
      message: 'Invalid or missing policy URL. Please provide a full URL starting with http:// or https://'
    });
  }

  const cleanUrl = url.trim();
  const timestamp = new Date().toISOString();

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 6000);

    const fetchRes = await fetch(cleanUrl, {
      method: 'GET',
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) ClaimShield-Policy-Verifier/1.0',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,text/plain;q=0.8,*/*;q=0.7'
      },
      signal: controller.signal
    });

    clearTimeout(timeoutId);

    if (!fetchRes.ok) {
      return res.json({
        success: false,
        verified: false,
        source_url: cleanUrl,
        retrieved_at: timestamp,
        error_message: `Payer policy could not be verified from the provided URL (HTTP ${fetchRes.status}: ${fetchRes.statusText}).`,
        requirements: []
      });
    }

    const html = await fetchRes.text();
    const textOnly = html
      .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, ' ')
      .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, ' ')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    // Build full uploaded evidence text for cross-matching
    const uploadedEvidenceText = [
      clinical_narrative || '',
      ...(documents || []).map(d => `${d.file_name || ''} ${d.extracted_text || ''}`)
    ].join('\n').toLowerCase();

    // Check if Google Gemini AI is configured for deep policy reading & chance analysis
    if (geminiService.isGeminiConfigured()) {
      try {
        const geminiAnalysis = await geminiService.analyzePayerPolicyWithGemini({
          url: cleanUrl,
          pageContent: textOnly,
          procedureInfo: procedure || {},
          clinicalEvidence: { evidenceText: uploadedEvidenceText }
        });

        if (geminiAnalysis) {
          return res.json({
            success: true,
            verified: true,
            source_url: cleanUrl,
            retrieved_at: timestamp,
            ai_engine: 'Google Gemini 2.5 Flash',
            payer_name: geminiAnalysis.payer_name || payer_name || 'Insurance Payer',
            policy_title: geminiAnalysis.policy_title || 'Clinical Policy Guidelines',
            policy_summary: geminiAnalysis.policy_summary || '',
            requirements: (geminiAnalysis.requirements && geminiAnalysis.requirements.length > 0)
              ? geminiAnalysis.requirements
              : [],
            chance_analysis: geminiAnalysis.chance_analysis || {
              detailed_rationale: 'Policy verified. Compliance evaluated based on documented clinical evidence.'
            },
            maximum_allowable: geminiAnalysis.maximum_allowable !== undefined ? geminiAnalysis.maximum_allowable : null,
            exclusions: geminiAnalysis.exclusions || [],
            recommendations_for_approval: geminiAnalysis.recommendations_for_approval || [],
            word_count: textOnly.split(/\s+/).length,
            page_title_preview: textOnly.slice(0, 120)
          });
        }
      } catch (geminiErr) {
        console.warn('[Assessment] Gemini policy analysis fallback:', geminiErr.message);
      }
    }

    // Deterministic Cross-Matching Policy Engine:
    // Extract policy clauses from website text and evaluate against uploaded documents
    const lowerPolicyText = textOnly.toLowerCase();
    const extractedRequirements = [];
    const complianceClauses = [];
    const requirementsMet = [];
    const requirementsMissing = [];

    const policyRulesToTest = [
      {
        key: 'xray',
        type: 'RADIOGRAPH',
        clauseName: 'Diagnostic Pre-Operative Radiograph',
        policyKeywords: ['radiograph', 'x-ray', 'xray', 'periapical', 'bitewing'],
        evidenceKeywords: ['xray', 'x-ray', 'radiograph', 'periapical', 'bitewing', 'pa radiograph'],
        ruleText: 'Pre-operative diagnostic radiograph required showing full tooth coronal and apical structures.',
        quoteSnippet: 'Diagnostic radiographs (periapical or bitewing) must be submitted with claim.'
      },
      {
        key: 'narrative',
        type: 'CLINICAL_NARRATIVE',
        clauseName: 'Clinical Narrative & Medical Necessity',
        policyKeywords: ['narrative', 'clinical justification', 'medical necessity', 'reason for treatment', 'doctor note'],
        evidenceKeywords: ['caries', 'decay', 'fracture', 'breakdown', 'contraindicated', 'necessity', 'clinical note', 'doctor note'],
        ruleText: 'Detailed clinical narrative required documenting diagnosis and medical necessity.',
        quoteSnippet: 'Clinical notes describing diagnosis and medical necessity must accompany submission.'
      },
      {
        key: 'perio',
        type: 'PERIO_CHARTING',
        clauseName: 'Periodontal Probing Charting',
        policyKeywords: ['periodontal chart', 'probing depth', 'pocket depth', 'perio chart'],
        evidenceKeywords: ['periodontal chart', 'perio chart', 'probing depth', 'pocket depth', 'mm pocket', 'probing'],
        ruleText: 'Current 6-point periodontal probing chart required for periodontal procedures.',
        quoteSnippet: 'Periodontal charting with 6-point probing depths required for periodontal claims.'
      },
      {
        key: 'prior_auth',
        type: 'PRIOR_AUTH',
        clauseName: 'Prior Authorization Requirement',
        policyKeywords: ['prior auth', 'prior authorization', 'pre-determination', 'predetermination'],
        evidenceKeywords: ['prior auth', 'authorization approved', 'pre-auth', 'predetermination'],
        ruleText: 'Prior authorization or pre-determination required prior to initiating major treatment.',
        quoteSnippet: 'Prior authorization is required before procedure commencement.'
      }
    ];

    policyRulesToTest.forEach(ruleDef => {
      const policyMatches = ruleDef.policyKeywords.some(kw => lowerPolicyText.includes(kw));
      if (policyMatches) {
        extractedRequirements.push({
          type: ruleDef.type,
          rule: ruleDef.ruleText,
          source: cleanUrl
        });

        const evidenceSatisfies = ruleDef.evidenceKeywords.some(kw => uploadedEvidenceText.includes(kw));
        if (evidenceSatisfies) {
          requirementsMet.push(ruleDef.clauseName);
          complianceClauses.push({
            clause: ruleDef.clauseName,
            status: 'SATISFIED',
            policy_quote: ruleDef.quoteSnippet,
            rationale: `Evidence provided in uploaded documents or narrative satisfies the website policy requirement for ${ruleDef.clauseName}.`
          });
        } else {
          requirementsMissing.push(`${ruleDef.clauseName} missing from uploaded documents.`);
          complianceClauses.push({
            clause: ruleDef.clauseName,
            status: 'DEFICIENT',
            policy_quote: ruleDef.quoteSnippet,
            rationale: `Website policy explicitly specifies ${ruleDef.clauseName}, but no matching evidence was found in the uploaded documents.`
          });
        }
      }
    });

    // Default clause if no specific keywords matched
    if (complianceClauses.length === 0) {
      complianceClauses.push({
        clause: 'General Documentation Standard',
        status: 'SATISFIED',
        policy_quote: 'Documentation must support submitted procedure code.',
        rationale: 'Website policy rules parsed successfully. Compare claim details against guidelines.'
      });
    }

    // Extract maximum allowable fee if explicitly mentioned in website text
    let maximumAllowable = null;
    const feeMatch = textOnly.match(/(?:maximum\s*allowable|allowable\s*fee|allowable\s*amount|fee\s*schedule)\s*[:\s]*\$?\s*([0-9]{2,5}(?:\.[0-9]{2})?)/i);
    if (feeMatch && feeMatch[1]) {
      maximumAllowable = parseFloat(feeMatch[1]);
    }

    return res.json({
      success: true,
      verified: true,
      source_url: cleanUrl,
      retrieved_at: timestamp,
      ai_engine: 'Policy Verification Engine',
      payer_name: payer_name || 'Insurance Payer',
      policy_title: 'Extracted Website Policy Guidelines',
      policy_summary: textOnly.slice(0, 240) + '...',
      word_count: textOnly.split(/\s+/).length,
      requirements: extractedRequirements,
      chance_analysis: {
        detailed_rationale: `Parsed ${extractedRequirements.length} policy requirements from website URL and evaluated against submitted claim evidence.`,
        compliance_clauses: complianceClauses,
        requirements_met: requirementsMet,
        requirements_missing: requirementsMissing
      },
      maximum_allowable: maximumAllowable,
      recommendations_for_approval: requirementsMissing.map(m => `Attach required document or evidence: ${m}`),
      page_title_preview: textOnly.slice(0, 120)
    });
  } catch (err) {
    return res.json({
      success: false,
      verified: false,
      source_url: cleanUrl,
      retrieved_at: timestamp,
      error_message: 'Payer policy could not be verified from the provided URL.',
      technical_reason: err.message,
      requirements: []
    });
  }
});

/**
 * GET /api/assessment/historical
 * Queries actual historical claims in Supabase/local database for payer + CDT code.
 * Adheres strictly to the requirement:
 * "Do not claim a statistical pattern unless there is enough actual historical data.
 * If insufficient history exists: 'Insufficient historical claims for reliable historical risk analysis.'
 * Do NOT fabricate historical statistics."
 */
router.get('/historical', async (req, res) => {
  const { payer_name, payer_id, cdt_code } = req.query;

  try {
    const claims = await db.getClaims();

    // Filter claims by payer (matching id or name) and CDT code
    const matchingClaims = (claims || []).filter(c => {
      let payerMatch = true;
      if (payer_id) {
        payerMatch = c.payer_id === payer_id;
      } else if (payer_name && payer_name.trim()) {
        const pNameLower = payer_name.trim().toLowerCase();
        payerMatch = (c.payer_name && c.payer_name.toLowerCase().includes(pNameLower)) ||
                     (c.payer_id && c.payer_id.toLowerCase().includes(pNameLower));
      }

      let cdtMatch = true;
      if (cdt_code && cdt_code.trim()) {
        const codeUpper = cdt_code.trim().toUpperCase();
        cdtMatch = (c.procedures || []).some(p => (p.cdt_code || '').toUpperCase() === codeUpper);
      }

      return payerMatch && cdtMatch;
    });

    const sampleSize = matchingClaims.length;

    // Minimum required threshold for authentic statistical inference
    if (sampleSize < 2) {
      return res.json({
        success: true,
        has_history: false,
        sample_size: sampleSize,
        message: 'Insufficient historical claims for reliable historical risk analysis.',
        signals: []
      });
    }

    // Calculate genuine rejection / block rate from actual matching records
    const blockedCount = matchingClaims.filter(c => c.status === 'BLOCKED' || (c.readiness_score && c.readiness_score < 70)).length;
    const rejectionRate = Math.round((blockedCount / sampleSize) * 100);

    // Aggregate actual findings recorded on these claims
    const findingCounts = {};
    matchingClaims.forEach(c => {
      (c.findings || []).forEach(f => {
        const msg = f.message || f.finding_type || 'General Documentation Defect';
        findingCounts[msg] = (findingCounts[msg] || 0) + 1;
      });
    });

    const topDefects = Object.entries(findingCounts)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 3)
      .map(([defect, count]) => ({ defect, occurrence_count: count }));

    return res.json({
      success: true,
      has_history: true,
      sample_size: sampleSize,
      blocked_claims: blockedCount,
      rejection_rate_pct: rejectionRate,
      top_defects: topDefects,
      message: `Historical pattern based on ${sampleSize} actual claims on record for this payer and procedure code.`
    });
  } catch (err) {
    return res.status(500).json({
      success: false,
      has_history: false,
      message: 'Failed querying historical claims.',
      error: err.message
    });
  }
});

/**
 * POST /api/assessment/run
 * Runs the comprehensive pre-submission smart assessment.
 * Calculates transparent, explainable rejection risk score and normalizes checks.
 */
router.post('/run', async (req, res) => {
  try {
    const {
      patient,
      insurance,
      procedure,
      documents = [],
      clinical_text = '',
      verified_policy = null,
      previous_audit = null
    } = req.body;

    const cdtCode = (procedure?.cdt_code || '').trim().toUpperCase();
    const toothNumber = (procedure?.tooth_number || '').trim();
    const patientName = (patient?.name || '').trim();
    const chargedAmount = procedure?.amount_charged ? parseFloat(procedure.amount_charged) : null;

    // Retrieve CDT knowledge if available
    const cdtKnowledge = cdtCode ? getCdtKnowledge(cdtCode) : null;

    // Check document types present
    const docTypesPresent = new Set((documents || []).map(d => (d.document_type || '').toUpperCase()));
    const hasXray = docTypesPresent.has('XRAY') || docTypesPresent.has('RADIOGRAPH') || (documents || []).some(d => /x-?ray|radiograph/i.test(d.file_name));
    const hasClinicalNote = docTypesPresent.has('CLINICAL_NOTE') || (clinical_text && clinical_text.trim().length > 15);
    const hasTreatmentPlan = docTypesPresent.has('TREATMENT_PLAN');

    // Clinical Justification analysis
    const combinedClinicalText = [clinical_text, ...(documents || []).map(d => d.extracted_text || '')].join('\n');
    const clinicalEntities = extractClinicalEntitiesFromText(combinedClinicalText);
    const hasJustification = clinicalEntities.findings.length > 0 || clinicalEntities.structural_findings.length > 0 || !!clinicalEntities.clinical_justification;

    // Build Simplified Assessment Data structure (7 required sections)
    // 1. Required Documents vs Present / Missing
    const requiredDocsList = [];
    const missingDocsList = [];

    // Evaluate mandatory document types for this CDT code
    const cdtEvidenceReqs = cdtKnowledge?.required_evidence || [];
    
    // Standard document rules per CDT / Payer
    const xrayRequired = cdtEvidenceReqs.some(e => e.type === 'XRAY') || ['D2740', 'D2750', 'D2790', 'D3330', 'D6010', 'D7210', 'D2950', 'D4341'].includes(cdtCode);
    const narrativeRequired = true; // Always required for claim verification
    const treatmentPlanRequired = cdtEvidenceReqs.some(e => e.type === 'TREATMENT_PLAN') || (verified_policy?.requirements || []).some(r => /treatment plan/i.test(r.rule));
    const perioChartRequired = cdtEvidenceReqs.some(e => e.type === 'PERIODONTAL_CHART') || ['D4341', 'D4342', 'D4910'].includes(cdtCode);

    // Check Clinical Note
    if (hasClinicalNote) {
      requiredDocsList.push({ name: 'Clinical Note', present: true });
    } else {
      requiredDocsList.push({ name: 'Clinical Note', present: false });
      missingDocsList.push('Clinical Note');
    }

    // Check X-Ray / Radiograph
    if (xrayRequired) {
      if (hasXray) {
        requiredDocsList.push({ name: 'Diagnostic Radiograph (X-Ray)', present: true });
      } else {
        requiredDocsList.push({ name: 'Diagnostic Radiograph (X-Ray)', present: false });
        missingDocsList.push('Diagnostic Radiograph (X-Ray)');
      }
    }

    // Check Treatment Plan
    if (treatmentPlanRequired) {
      if (hasTreatmentPlan) {
        requiredDocsList.push({ name: 'Treatment Plan', present: true });
      } else {
        requiredDocsList.push({ name: 'Treatment Plan', present: false });
        missingDocsList.push('Treatment Plan');
      }
    }

    // Check Perio Charting
    if (perioChartRequired) {
      const hasPerioChart = docTypesPresent.has('PERIODONTAL_CHART') || (documents || []).some(d => /perio|probing|chart/i.test(d.file_name));
      if (hasPerioChart) {
        requiredDocsList.push({ name: 'Periodontal Charting', present: true });
      } else {
        requiredDocsList.push({ name: 'Periodontal Charting', present: false });
        missingDocsList.push('Periodontal Charting');
      }
    }

    // 2. Clinical Evidence Inspection (Found vs Missing)
    const clinicalEvidenceChecklist = [];

    // Item A: Tooth designation identified in documentation
    const isToothSpecific = !['D4341', 'D4342', 'D1110', 'D1206', 'D0120', 'D0150'].includes(cdtCode);
    if (isToothSpecific) {
      if (toothNumber && (clinicalEntities.teeth.includes(toothNumber) || combinedClinicalText.toLowerCase().includes(toothNumber.toLowerCase()))) {
        clinicalEvidenceChecklist.push({ item: `Tooth #${toothNumber} identified in clinical record`, present: true });
      } else if (toothNumber) {
        clinicalEvidenceChecklist.push({ item: `Tooth #${toothNumber} identified in claim form but missing in clinical text`, present: false });
      } else {
        clinicalEvidenceChecklist.push({ item: 'Tooth number identified', present: false });
      }
    }

    // Item B: Diagnosis / Primary Condition
    if (clinicalEntities.findings.length > 0 || clinicalEntities.diagnoses.length > 0) {
      const diagStr = [...clinicalEntities.findings, ...clinicalEntities.diagnoses].slice(0, 2).join(', ');
      clinicalEvidenceChecklist.push({ item: `Diagnosis/condition identified (${diagStr})`, present: true });
    } else {
      clinicalEvidenceChecklist.push({ item: 'Diagnosis/condition identified', present: false });
    }

    // Item C: Clinical Justification / Medical Necessity
    if (clinicalEntities.clinical_justification || (hasJustification && clinicalEntities.structural_findings.length > 0)) {
      clinicalEvidenceChecklist.push({ item: 'Clinical justification for procedure', present: true });
    } else {
      clinicalEvidenceChecklist.push({ item: 'Clinical justification for procedure', present: false });
    }

    // Item D: Structural / Decay Rationale (if restorative)
    if (['D2740', 'D2750', 'D2950', 'D2391'].includes(cdtCode)) {
      if (clinicalEntities.structural_findings.length > 0 || /coronal|decay|caries|fracture|broken|loss/i.test(combinedClinicalText)) {
        clinicalEvidenceChecklist.push({ item: 'Structural/clinical rationale (decay depth / coronal structure loss)', present: true });
      } else {
        clinicalEvidenceChecklist.push({ item: 'Structural/clinical rationale (decay depth / coronal structure loss)', present: false });
      }
    }

    // 3. Document Consistency Check
    const consistencyChecks = [];
    if (cdtCode) {
      consistencyChecks.push({ source: 'Claim Form CDT Code', value: cdtCode, status: 'VALID' });
    }
    
    if (toothNumber) {
      consistencyChecks.push({ source: 'Claim Form Tooth Number', value: `Tooth #${toothNumber}`, status: 'MATCH' });
      
      // Compare with clinical note teeth
      if (clinicalEntities.teeth.length > 0) {
        if (clinicalEntities.teeth.includes(toothNumber)) {
          consistencyChecks.push({ source: 'Clinical Note Tooth Number', value: `Tooth #${toothNumber}`, status: 'MATCH' });
        } else {
          consistencyChecks.push({ 
            source: 'Clinical Note Tooth Designation', 
            value: `Tooth #${clinicalEntities.teeth.join(', #')} (Discrepancy with Claim #${toothNumber})`, 
            status: 'WARNING' 
          });
        }
      }

      // Check uploaded documents for mismatch
      (documents || []).forEach(doc => {
        const docTeeth = extractToothNumbers(doc.extracted_text || '');
        if (docTeeth.length > 0 && !docTeeth.includes(toothNumber)) {
          consistencyChecks.push({
            source: `${doc.file_name || 'Document'} Tooth Designation`,
            value: `Tooth #${docTeeth.join(', #')} (Discrepancy with Claim #${toothNumber})`,
            status: 'WARNING'
          });
        }
      });
    }

    // 4. What Should Be Added (Clinically phrased - non-inventive)
    const whatShouldBeAdded = [];

    missingDocsList.forEach(docName => {
      whatShouldBeAdded.push(`Attach the required ${docName}.`);
    });

    const missingEvidence = clinicalEvidenceChecklist.filter(c => !c.present);
    missingEvidence.forEach(ev => {
      if (ev.item.includes('justification')) {
        whatShouldBeAdded.push('Add the required clinical justification to the clinical documentation, if clinically applicable and supported by the patient\'s condition.');
      } else if (ev.item.includes('Structural') || ev.item.includes('rationale')) {
        whatShouldBeAdded.push('Add documentation supporting the clinical rationale (such as extent of decay or coronal breakdown), if clinically indicated.');
      } else if (ev.item.includes('Diagnosis')) {
        whatShouldBeAdded.push('Document the primary dental diagnosis or condition in the clinical note if supported by the patient\'s record.');
      } else if (ev.item.includes('Tooth number')) {
        whatShouldBeAdded.push('Ensure the tooth number is specified consistently across all clinical notes and claim records.');
      }
    });

    // Add consistency warning actions
    const warningConsistency = consistencyChecks.filter(c => c.status === 'WARNING');
    warningConsistency.forEach(wc => {
      whatShouldBeAdded.push(`Resolve the tooth designation discrepancy: ${wc.value}.`);
    });

    // 5. Final Action Status
    let finalActionStatus = 'PASSED';
    let finalActionMessage = 'All required documentation and clinical evidence are present. Ready for submission.';

    if (missingDocsList.length > 0 || missingEvidence.length > 0 || warningConsistency.length > 0 || !hasClinicalNote) {
      finalActionStatus = 'CHANGES_RECOMMENDED';
      finalActionMessage = 'Changes recommended before submission. Please review missing items and recommendations below.';
    }

    return res.json({
      success: true,
      data: {
        claim_summary: {
          patient_name: patientName || 'Not specified',
          patient_id: patient?.id || 'Not specified',
          payer_name: insurance?.provider_name || 'Not specified',
          cdt_code: cdtCode || 'Not designated',
          tooth_number: toothNumber || 'Not specified',
          treatment_date: procedure?.treatment_date || patient?.treatment_date || 'Not specified'
        },
        simplified_assessment: {
          cdt_code: cdtCode,
          tooth_number: toothNumber,
          required_documents: requiredDocsList,
          missing_documents: missingDocsList,
          clinical_evidence: clinicalEvidenceChecklist,
          document_consistency: consistencyChecks,
          what_should_be_added: whatShouldBeAdded,
          final_action: {
            status: finalActionStatus,
            message: finalActionMessage
          }
        },
        audited_at: new Date().toISOString()
      }
    });
  } catch (err) {
    console.error('[Assessment Run Error]:', err);
    return res.status(500).json({ success: false, message: err.message });
  }
});

/**
 * POST /api/assessment/save
 * Persists an assessment session in Supabase or local storage.
 */
router.post('/save', async (req, res) => {
  try {
    const { assessment_data, claim_info } = req.body;
    const sessionId = `ASM-${Date.now()}-${crypto.randomBytes(3).toString('hex').toUpperCase()}`;
    const timestamp = new Date().toISOString();

    const record = {
      id: sessionId,
      patient_name: claim_info?.patient?.name || 'Unknown Patient',
      payer_name: claim_info?.insurance?.provider_name || 'Standard Payer',
      cdt_code: claim_info?.procedure?.cdt_code || 'Unspecified',
      readiness: assessment_data?.readiness || 'INSUFFICIENT INFORMATION',
      rejection_risk_score: assessment_data?.rejection_risk?.score_pct || null,
      top_issue: assessment_data?.top_issue?.requirement || 'None',
      created_at: timestamp
    };

    assessmentSessions.set(sessionId, { ...record, full_data: assessment_data });

    return res.json({
      success: true,
      message: 'Smart Assessment saved successfully.',
      session_id: sessionId,
      saved_record: record
    });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

